import type { ShortcutRegistry } from "./model.ts";

/** Path of the generated registry module, from the package root. */
export const GENERATED_PATH = "src/shortcuts/registry.generated.ts";

/** The generated TypeScript module holding the shortcut registry, for apps that cannot read files. */
export function renderShortcutRegistryModule(registry: ShortcutRegistry): string {
  return [
    "// Generated by `pnpm --filter @xos/schemas generate:shortcuts` from packages/schemas/shortcuts.yaml.",
    "// Never edit by hand; on a merge conflict, take either side and rerun the generator.",
    'import type { ShortcutRegistry } from "./model.ts";',
    "",
    `export const SHORTCUT_REGISTRY: ShortcutRegistry = ${JSON.stringify(registry, null, 2)};`,
    "",
  ].join("\n");
}
